me: portName, TargetPort: intstr.FromInt32(port)}, 				}, 			}, 		} 		return r.Create(ctx, svc) 	} 	return err }  func (r *FlinkClusterReconciler) reconcileOpenShiftRoute(ctx context.Context, ns, name, svcName string, owner *corev1.ConfigMap) error { 	foundRoute := &routev1.Route{} 	err := r.Get(ctx, client.ObjectKey{Namespace: ns, Name: name}, foundRoute) 	if err != nil && errors.IsNotFound(err) { 		route := &routev1.Route{ 			ObjectMeta: metav1.ObjectMeta{ 				Name:      name, 				Namespace: ns, 				OwnerReferences: []metav1.OwnerReference{ 					*metav1.NewControllerRef(owner, owner.GroupVersionKind()), 				}, 			}, 			Spec: routev1.RouteSpec{ 				To: routev1.RouteTargetReference{ 					Kind: "Service", 					Name: svcName, 				}, 				Port: &routev1.RoutePort{ 					TargetPort: intstr.FromString("ui"), 				}, 				TLS: &routev1.TLSConfig{ 					Termination:                   routev1.TLSTerminationEdge, 					InsecureEdgeTerminationPolicy: routev1.InsecureEdgeTerminationPolicyRedirect, 				}, 			}, 		} 		return r.Create(ctx, route) 	} 	return err }  // FEATURE 1 Implementation: Programmatic NetworkPolicy Security Boundary func (r *FlinkClusterReconciler) reconcileNetworkPolicy(ctx context.Context, ns, name, clusterName string, owner *corev1.ConfigMap) error { 	foundNP := &networkingv1.NetworkPolicy{} 	err := r.Get(ctx, client.ObjectKey{Namespace: ns, Name: name}, foundNP)  	desiredNP := &networkingv1.NetworkPolicy{ 		ObjectMeta: metav1.ObjectMeta{ 			Name:      name, 			Namespace: ns, 			OwnerReferences: []metav1.OwnerReference{ 				*metav1.NewControllerRef(owner, owner.GroupVersionKind()), 			}, 		}, 		Spec: networkingv1.NetworkPolicySpec{ 			// Target all components matching this specific Flink Cluster label 			PodSelector: metav1.LabelSelector{ 				MatchLabels: map[string]string{"flink-cluster": clusterName}, 			}, 			PolicyTypes: []networkingv1.PolicyType{networkingv1.PolicyTypeIngress}, 			Ingress: []networkingv1.NetworkPolicyIngressRule{ 				{ 					// Rule A: Allow