er %s\"}' %s", preStopCommand, owner.Name, webhookURL) 	} else { 		preStopCommand = fmt.Sprintf("%s || true", preStopCommand) 	}  	replicas := int32(1) 	desiredDeployment := &appsv1.Deployment{ 		ObjectMeta: metav1.ObjectMeta{ 			Name:      name, 			Namespace: ns, 			OwnerReferences: []metav1.OwnerReference{ 				*metav1.NewControllerRef(owner, owner.GroupVersionKind()), 			}, 		}, 		Spec: appsv1.DeploymentSpec{ 			Replicas: &replicas, 			Selector: &metav1.LabelSelector{MatchLabels: map[string]string{"flink-role": "jobmanager", "flink-cluster": owner.Name}}, 			Template: corev1.PodTemplateSpec{ 				Metadata: metav1.ObjectMeta{Labels: map[string]string{"flink-role": "jobmanager", "flink-cluster": owner.Name}}, 				Spec: corev1.PodSpec{ 					Containers: []corev1.Container{{ 						Name:  "jobmanager", 						Image: image, 						Args:  commandArgs, 						Ports: []corev1.ContainerPort{ 							{ContainerPort: 6123, Name: "rpc"}, 							{ContainerPort: 8081, Name: "ui"}, 						}, 						Env: []corev1.EnvVar{ 							{Name: "JOB_MANAGER_RPC_ADDRESS", Value: fmt.Sprintf("%s-jobmanager-rpc", owner.Name)}, 						}, 						Lifecycle: &corev1.Lifecycle{ 							PreStop: &corev1.LifecycleHandler{ 								Exec: &corev1.ExecAction{ 									Command: []string{"/bin/sh", "-c", preStopCommand}, 								}, 							}, 						}, 						VolumeMounts: []corev1.VolumeMount{{ 							Name:      "flink-shared-storage", 							MountPath: "/opt/flink/data", 						}}, 					}}, 					Volumes: []corev1.Volume{{ 						Name: "flink-shared-storage", 						VolumeSource: corev1.VolumeSource{ 							EmptyDir: &corev1.EmptyDirVolumeSource{}, 						}, 					}}, 				}, 			}, 		}, 	}  	if err != nil && errors.IsNotFound(err) { 		return r.Create(ctx, desiredDeployment) 	} else if err == nil { 		if foundJM.Spec.Template.Spec.Containers.Image != image { 			foundJM.Spec.Template.Spec.Containers.Image = image`

